import {
  INACTIVE_STROKE_ONLY_OPACITY_BAND_CHART,
  STROKE_ONLY_OPACITY_BAND_CHART,
  INACTIVE_FILL_OPACITY_BAND_CHART,
  DEFAULT_OPACITY_BAND_CHART,
} from '../../../../core/constants.js';
import { ShapeColor } from '../../../../core/types/color-palette.js';
import { SeriesMetadata } from '../../../types/timeseries.js';

export const getBandStyle = (
  seriesMetadata: SeriesMetadata,
  highlightedSeriesId?: string[],
  strokeOnly?: boolean,
): Required<ShapeColor> => {
  const isHighlightedSeries = highlightedSeriesId?.includes(seriesMetadata.id);

  const areOtherSeriesHighlighted = !!highlightedSeriesId;

  if (strokeOnly) {
    return {
      color: 'transparent',
      stroke: seriesMetadata.color.Default,
      opacity: isHighlightedSeries
        ? STROKE_ONLY_OPACITY_BAND_CHART
        : areOtherSeriesHighlighted
        ? INACTIVE_STROKE_ONLY_OPACITY_BAND_CHART
        : STROKE_ONLY_OPACITY_BAND_CHART,
    };
  }

  if (isHighlightedSeries) {
    return {
      color: seriesMetadata.color.Default,
      stroke: seriesMetadata.color.Default,
      opacity: DEFAULT_OPACITY_BAND_CHART,
    };
  }

  return {
    color: seriesMetadata.color.Default,
    stroke: seriesMetadata.color.Default,
    opacity: areOtherSeriesHighlighted
      ? INACTIVE_FILL_OPACITY_BAND_CHART
      : DEFAULT_OPACITY_BAND_CHART,
  };
};
